"""World and approval epochs: fail-closed identity for cache reuse.

The epoch module implements one of the four planes taught in Week 4: the
external-world and approval authority plane.  A ``WorldStamp`` is an immutable
fingerprint of everything a model-visible continuation is allowed to assume:
the workspace identity, the observed file digests, the enabled tool catalog,
and the approval policy version.  Reusing a KV cache, an approval, or an undo
plan across a mismatched stamp is always a bug; every entry point fails closed
instead of guessing.
"""

from __future__ import annotations

import hashlib
from dataclasses import dataclass
from pathlib import Path
from typing import Any


class EpochMismatch(RuntimeError):
    """A cached continuation is bound to a world/approval epoch that is stale."""

    def __init__(self, message: str):
        self.message = message
        super().__init__(message)


def _json_copy(value: Any) -> Any:
    """Validate and detach a JSON-compatible epoch payload."""

    try:
        return __import__("json").loads(
            __import__("json").dumps(
                value, ensure_ascii=True, sort_keys=True, separators=(",", ":")
            )
        )
    except (TypeError, ValueError) as error:
        raise ValueError("epoch payload must be JSON serializable") from error


def _stable_json(value: Any) -> bytes:
    """Serialize a JSON payload into stable canonical bytes."""

    return (
        __import__("json")
        .dumps(value, ensure_ascii=True, sort_keys=True, separators=(",", ":"))
        .encode("utf-8")
    )


@dataclass(frozen=True)
class WorldStamp:
    """Immutable fingerprint of the workspace-visible world at one moment.

    Fields
    ------
    epoch:
        A monotonically increasing counter.  Any external mutation, tool-list
        change, permission change, or effectful replay must increment it.
    root:
        The resolved workspace root path (identity, not contents).
    observed_digests:
        Sorted ``(relative_path, sha256)`` pairs for every file the harness has
        read, so a later continuation can prove its observations are current.
    tool_catalog_hash:
        Hash of the enabled tool schema catalog.  Changing the tool set must
        invalidate every cache continuation bound to the old catalog.
    approval_epoch:
        Version of the approval policy.  Revoking an approval must invalidate
        cached continuations that assumed the old approval state.
    """

    epoch: int
    root: str
    observed_digests: tuple[tuple[str, str], ...] = ()
    tool_catalog_hash: str = ""
    approval_epoch: int = 0

    def digest(self) -> str:
        """Return a stable content hash of this stamp."""

        return hashlib.sha256(
            _stable_json(
                {
                    "epoch": self.epoch,
                    "root": self.root,
                    "observed_digests": self.observed_digests,
                    "tool_catalog_hash": self.tool_catalog_hash,
                    "approval_epoch": self.approval_epoch,
                }
            )
        ).hexdigest()

    def require_current(self, expected: "WorldStamp") -> None:
        """Fail closed unless this stamp is exactly the expected current stamp.

        KV equality never implies world equality.  A stamp is authoritative only
        when it matches the live stamp produced by the harness at the same
        boundary; any difference (including an older epoch with identical file
        digests) is treated as stale.
        """

        if self.epoch != expected.epoch:
            raise EpochMismatch(
                f"world epoch mismatch: cached {self.epoch}, current {expected.epoch}"
            )
        if self.root != expected.root:
            raise EpochMismatch("world stamp root mismatch")
        if self.tool_catalog_hash != expected.tool_catalog_hash:
            raise EpochMismatch("tool catalog changed since this stamp")
        if self.approval_epoch != expected.approval_epoch:
            raise EpochMismatch("approval policy changed since this stamp")
        if self.observed_digests != expected.observed_digests:
            raise EpochMismatch("observed file digests changed since this stamp")

    def with_observed(self, relative: str, digest: str) -> "WorldStamp":
        """Return a new stamp that additionally records one observed digest."""

        merged = dict(self.observed_digests)
        merged[relative] = digest
        return WorldStamp(
            epoch=self.epoch,
            root=self.root,
            observed_digests=tuple(sorted(merged.items())),
            tool_catalog_hash=self.tool_catalog_hash,
            approval_epoch=self.approval_epoch,
        )

    def to_dict(self) -> dict[str, Any]:
        return _json_copy(
            {
                "epoch": self.epoch,
                "root": self.root,
                "observed_digests": self.observed_digests,
                "tool_catalog_hash": self.tool_catalog_hash,
                "approval_epoch": self.approval_epoch,
            }
        )

    @classmethod
    def from_dict(cls, value: Any) -> "WorldStamp":
        if not isinstance(value, dict) or set(value) != {
            "epoch",
            "root",
            "observed_digests",
            "tool_catalog_hash",
            "approval_epoch",
        }:
            raise ValueError("invalid world stamp fields")
        epoch = value["epoch"]
        root = value["root"]
        observed = value["observed_digests"]
        catalog_hash = value["tool_catalog_hash"]
        approval_epoch = value["approval_epoch"]
        if isinstance(epoch, bool) or not isinstance(epoch, int) or epoch < 0:
            raise ValueError("invalid world epoch")
        if not isinstance(root, str) or not root:
            raise ValueError("invalid world stamp root")
        if not isinstance(observed, list) or not all(
            isinstance(pair, list)
            and len(pair) == 2
            and isinstance(pair[0], str)
            and isinstance(pair[1], str)
            for pair in observed
        ):
            raise ValueError("invalid observed digests")
        if not isinstance(catalog_hash, str):
            raise ValueError("invalid tool catalog hash")
        if (
            isinstance(approval_epoch, bool)
            or not isinstance(approval_epoch, int)
            or approval_epoch < 0
        ):
            raise ValueError("invalid approval epoch")
        return cls(
            epoch=epoch,
            root=root,
            observed_digests=tuple(sorted((pair[0], pair[1]) for pair in observed)),
            tool_catalog_hash=catalog_hash,
            approval_epoch=approval_epoch,
        )


@dataclass(frozen=True)
class ApprovalEpoch:
    """Immutable version of the approval authority plane.

    The approval epoch is capability state, not conversation text.  A receipt
    or cache continuation is valid only while its recorded approval epoch still
    matches the operator's live approval epoch; revoking any approval must
    bump the counter so stale continuations fail closed.
    """

    epoch: int
    allowed_commands: tuple[tuple[str, ...], ...] = ()
    allow_writes: bool = False

    def digest(self) -> str:
        return hashlib.sha256(
            _stable_json(
                {
                    "epoch": self.epoch,
                    "allowed_commands": self.allowed_commands,
                    "allow_writes": self.allow_writes,
                }
            )
        ).hexdigest()

    def require_current(self, expected: "ApprovalEpoch") -> None:
        """Fail closed unless this approval state is exactly the current one."""

        if self.epoch != expected.epoch:
            raise EpochMismatch(
                f"approval epoch mismatch: cached {self.epoch}, "
                f"current {expected.epoch}"
            )
        if self.allowed_commands != expected.allowed_commands:
            raise EpochMismatch("allowed command set changed since this approval")
        if self.allow_writes != expected.allow_writes:
            raise EpochMismatch("write permission changed since this approval")

    def to_dict(self) -> dict[str, Any]:
        return _json_copy(
            {
                "epoch": self.epoch,
                "allowed_commands": self.allowed_commands,
                "allow_writes": self.allow_writes,
            }
        )

    @classmethod
    def from_dict(cls, value: Any) -> "ApprovalEpoch":
        if not isinstance(value, dict) or set(value) != {
            "epoch",
            "allowed_commands",
            "allow_writes",
        }:
            raise ValueError("invalid approval epoch fields")
        epoch = value["epoch"]
        commands = value["allowed_commands"]
        allow_writes = value["allow_writes"]
        if isinstance(epoch, bool) or not isinstance(epoch, int) or epoch < 0:
            raise ValueError("invalid approval epoch")
        if not isinstance(commands, list) or not all(
            isinstance(command, list)
            and command
            and all(isinstance(part, str) and part for part in command)
            for command in commands
        ):
            raise ValueError("invalid allowed command set")
        if not isinstance(allow_writes, bool):
            raise ValueError("invalid write permission")
        return cls(
            epoch=epoch,
            allowed_commands=tuple(tuple(command) for command in commands),
            allow_writes=allow_writes,
        )


def snapshot_world(
    root: Path,
    observed: dict[Path, bytes],
    *,
    tool_catalog_hash: str = "",
    approval_epoch: int = 0,
    world_epoch: int = 0,
) -> WorldStamp:
    """Build a deterministic world stamp from a root and observed digests."""

    root = root.resolve()
    return WorldStamp(
        epoch=world_epoch,
        root=str(root),
        observed_digests=tuple(
            sorted(
                (str(relative), digest.hex()) for relative, digest in observed.items()
            )
        ),
        tool_catalog_hash=tool_catalog_hash,
        approval_epoch=approval_epoch,
    )
